// Host adapters for the original 3.6556.2 ccd_turn server (electron/generated/turn-plan/ccd-turn.mjs, generated by
// scripts/extract-turn-plan.mjs). The generator checks each adapter still stands for the same original declaration.
//
// growthBookOn     index.chunk-jPKPzV-P.js m0 (`Pb`; 2.42304.0 muI2IV6k LZ `hy`): a GrowthBook flag. The ccd_turn tools
//                  read one flag, st() = m0("2371478310"). OpenClaude Desktop has no GrowthBook; the user asked for the
//                  task list in every session ("把这个 to do UI 也弄上"), so that flag is on here, like the turn box itself
//                  (D10 presets, D49). Every other flag is off, the host's usual default (D29/D31).
// growthBookValue  index.chunk-jPKPzV-P.js h0 (`Fb`, new in 3.6556.2): a GrowthBook flag with a default, `n?.on ?? t`.
//                  The ccd_turn server reads two:
//                    - 700252341 (Et, default on): the wrap_up result carries the `claude/endTurn` meta when the box
//                      shows the question. 2.42304.0 did this without a flag, so the default stands (no change).
//                    - 2833454025 (Dt, default on): the closing message follows the box (wrap_up description kt, and no
//                      endTurn meta: `ie=re&&!(i.closingFollowsQuestion??Dt())`). The official default stands
//                      (w8-turn-plan-renderer): the renderer reads that closing message as the 3.6556.2 turn tail does
//                      (src/generated/turn-plan/turn-tail.mjs c4ea84cb3 Br `closingMessageFollows:he!==null&&Lr(e,he)`),
//                      and the host next-step row passes it to ZA as cccc2cf0a cj does (src/source-turn-box.jsx).
//                  Every other flag is off.
// logEvent         index.chunk-jPKPzV-P.js uz (`Q`; 2.42304.0 iz): event logging (desktop_ccd_turn_scope). Nothing is
//                  sent (D17).
export const TURN_TOOLS_FLAG = "2371478310";
export const END_TURN_META_FLAG = "700252341";
export const CLOSING_MESSAGE_FOLLOWS_FLAG = "2833454025";

export function growthBookOn(flag) {
  return flag === TURN_TOOLS_FLAG;
}

export function growthBookValue(flag, fallback) {
  if (flag === END_TURN_META_FLAG || flag === CLOSING_MESSAGE_FOLLOWS_FLAG) return fallback;
  return false;
}

export function logEvent() {}
